-- ============================================================================
-- B5 FOLLOW-ON W5A (leak re-case and strip): seismolord.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 3
-- (D4 A and B, D5). Spec: docs/graded-field-audit/w5/seismolord.json. The new
-- keys come from tools/course-waves/w5/seismolord/fields.json,
-- written by the course's engine generator and re-checked in CI.
--
-- BEGINNER: pick A (re-case)
--   Every field leaked: the walkthrough and the synthetic lessons printed them
--   and the synthetic explorer opened on the capstone setting (whole log, 2000
--   m/s, 25 Hz). The capstone moves to the UBIMA case, a depth window of the log
--   with an overburden velocity and a wavelet of its own, typed into the
--   synthetic explorer (the velocity and the window are new inputs).
--   mean_velocity_ms (3145.2869374221345, tol 1)
--       -> ubima_mean_velocity_ms 'Mean sonic velocity in the window' m/s, expected 2991.2286066090837, tol 0.05
--   twt_at_log_top_ms (1500, tol 0.5)
--       -> ubima_twt_at_window_top_ms 'TWT at the top of the window' ms, expected 1300, tol 0.05
--   imp_max (10624.9560546875, tol 10)
--       -> ubima_imp_max 'Maximum impedance in the window' (m/s)·(g/cc), expected 10474.98046875, tol 0.05
--   rc_peak_abs (0.017688043415546417, tol 0.0005)
--       -> ubima_rc_peak_abs 'Strongest reflection coefficient (abs)' -, expected 0.021212393417954445, tol 5e-05
--   rc_peak_twt_ms (1582, tol 2)
--       -> ubima_rc_peak_twt_ms 'TWT of the strongest reflection' ms, expected 1318, tol 0.5
--   syn_peak_twt_ms (1642, tol 2)
--       -> ubima_syn_peak_twt_ms 'TWT of the strongest synthetic amplitude (30 Hz)' ms, expected 1360, tol 0.5
--   TITLE was: Tie the basic_20 well: synthetic seismogram summary
--   TITLE now: Tie the basic_20 well: the UBIMA window
--   DATASET was: wells/las/basic_20 + ricker25
--   DATASET now: wells/las/basic_20, UBIMA window and time-depth (W5 re-case;
--   every setting is stated in the brief)
--   PROMPT now: Build the synthetic for the UBIMA window of the basic_20
--   teaching well: the log from 1560 to 1640 m MD, a vertical well with the KB
--   at MSL and a single 2400 m/s overburden velocity (so TWT = 2z/2400 s), and a
--   30 Hz Ricker wavelet on the 2 ms grid. Type the window, the velocity and the
--   frequency into the synthetic explorer (it opens on the whole log at 2000 m/s
--   and 25 Hz, which is the teaching case) and read the summary: report the mean
--   sonic velocity in the window, the two-way time at the top of the window, the
--   maximum impedance, the strongest reflection coefficient (absolute value) and
--   its two-way time, and the two-way time of the strongest synthetic amplitude.
--
-- INTERMEDIATE: pick B (strip)
--   B strip. The lessons now work a teaching trace arriving 6 ms late (they said
--   8 ms, the answer, in 17 places) and never print the brief trace's zero-lag
--   correlation; the shift explorer opens on the teaching trace and runs the
--   brief's trace, lag withheld, only when selected. The brief names that
--   setting. Keys, values and tolerances do not move. The open-book label stays,
--   because the module lessons still print the 15 and 40 Hz peak readings, which
--   the B5 audit did not classify as leaks.
--   PROMPT now: Open book, in part: some of the figures this capstone grades can
--   be read in this tier's lessons or on a panel as it opens, so for now those
--   check that you can find, read and report them correctly. A later update
--   takes them out of the lessons and panels. The observed seismic trace is the
--   25 Hz synthetic arriving late by a lag this brief does not state. Run the
--   bulk-shift scan on this trace (the shift explorer's Observed trace setting
--   "The brief's trace"; the panel opens on a teaching trace) and read the
--   panel: the suggested shift, and the correlation at zero lag, which is what
--   the tie scores if you never shift it. Then flip the wavelet between 15 and
--   40 Hz and report the strongest synthetic amplitude and its time at each
--   frequency. Tuning moves both.
--
-- ATTEMPTS. Tiers whose graded keys move: seismolord/beginner. Before it
-- writes, the file counts academy_capstone_attempts on each and REFUSES if any
-- exist, unless D5 allowlists that tier with the exact attempt ids (allowlist:
-- empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its post-W1 form (prompt, title and
-- dataset by md5, fields as exact jsonb), which is rewritten, OR its W5 form,
-- which is left alone. Anything else raises and the whole file rolls back.
-- Generated by docs/graded-field-audit/w5_capstones.py. SAFE TO RE-RUN: a
-- second run writes nothing.
--
-- NOT A DB STEP. The lessons and panels that go with this file ship in the
-- NextGen zip, which must go live at nearly the same time as this apply.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- seismolord / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w5a seismolord refused: seismolord/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'c81a13bbfe68c6f97d4f66f5903ea57b' and md5(coalesce(title, '')) = '734b1f0d9d6a95b3216ce06b182c3c78' and md5(coalesce(dataset, '')) = '21f2067f02819ff5a38def144442cebe' and fields = '[{"key": "mean_velocity_ms", "tol": 1, "unit": "m/s", "label": "Mean sonic velocity", "expected": 3145.2869374221345}, {"key": "twt_at_log_top_ms", "tol": 0.5, "unit": "ms", "label": "TWT at the top of the log", "expected": 1500}, {"key": "imp_max", "tol": 10, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance", "expected": 10624.9560546875}, {"key": "rc_peak_abs", "tol": 0.0005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.017688043415546417}, {"key": "rc_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1582}, {"key": "syn_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (25 Hz)", "expected": 1642}]'::jsonb then 'old'
              when md5(prompt) = '504c5962361e12aa8d3e607a99ecc5a2' and md5(coalesce(title, '')) = 'a3328273ed6e1f5e5cf888bd950b1ff7' and md5(coalesce(dataset, '')) = '46d7bac23cbee5cce31aab5e625bea31' and fields = '[{"key": "ubima_mean_velocity_ms", "tol": 0.05, "unit": "m/s", "label": "Mean sonic velocity in the window", "expected": 2991.2286066090837}, {"key": "ubima_twt_at_window_top_ms", "tol": 0.05, "unit": "ms", "label": "TWT at the top of the window", "expected": 1300}, {"key": "ubima_imp_max", "tol": 0.05, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance in the window", "expected": 10474.98046875}, {"key": "ubima_rc_peak_abs", "tol": 5e-05, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.021212393417954445}, {"key": "ubima_rc_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1318}, {"key": "ubima_syn_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (30 Hz)", "expected": 1360}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w5a seismolord refused: seismolord/beginner matches neither its post-W1 form (prompt md5 c81a13bbfe68c6f97d4f66f5903ea57b) nor its W5 form (prompt md5 504c5962361e12aa8d3e607a99ecc5a2), with the fields this file was generated against';
  end if;

  -- seismolord / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w5a seismolord refused: seismolord/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '0586befbe8a90da6228d5b53750c46fb' and md5(coalesce(title, '')) = '48900a1c111c4c3e19996a98eda068ce' and md5(coalesce(dataset, '')) = '8006e0e511b8e482f3dcbc2ccf7900c8' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'old'
              when md5(prompt) = 'f00631b6f0fdf97f60cb989df036ee2d' and md5(coalesce(title, '')) = '48900a1c111c4c3e19996a98eda068ce' and md5(coalesce(dataset, '')) = '8006e0e511b8e482f3dcbc2ccf7900c8' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w5a seismolord refused: seismolord/intermediate matches neither its post-W1 form (prompt md5 0586befbe8a90da6228d5b53750c46fb) nor its W5 form (prompt md5 f00631b6f0fdf97f60cb989df036ee2d), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W5 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w5a seismolord: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- ATTEMPTS. A tier whose graded keys this file moves must hold no capstone
  -- attempt (a stored score is never re-scored, but a learner could be graded
  -- differently on a retry), unless D5 allowlists it with the exact attempt
  -- ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'seismolord' and a.tier = 'beginner';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'seismolord/beginner' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'seismolord/beginner') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w5a seismolord refused: seismolord/beginner holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w5a seismolord: seismolord/beginner holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w5a seismolord refused: seismolord/beginner holds % capstone attempt(s) (%) and this file moves its graded keys; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Build the synthetic for the UBIMA window of the basic_20 teaching well: the log from 1560 to 1640 m MD, a vertical well with the KB at MSL and a single 2400 m/s overburden velocity (so TWT = 2z/2400 s), and a 30 Hz Ricker wavelet on the 2 ms grid. Type the window, the velocity and the frequency into the synthetic explorer (it opens on the whole log at 2000 m/s and 25 Hz, which is the teaching case) and read the summary: report the mean sonic velocity in the window, the two-way time at the top of the window, the maximum impedance, the strongest reflection coefficient (absolute value) and its two-way time, and the two-way time of the strongest synthetic amplitude.',
           title = 'Tie the basic_20 well: the UBIMA window',
           dataset = 'wells/las/basic_20, UBIMA window and time-depth (W5 re-case; every setting is stated in the brief)',
           fields = '[{"key": "ubima_mean_velocity_ms", "tol": 0.05, "unit": "m/s", "label": "Mean sonic velocity in the window", "expected": 2991.2286066090837}, {"key": "ubima_twt_at_window_top_ms", "tol": 0.05, "unit": "ms", "label": "TWT at the top of the window", "expected": 1300}, {"key": "ubima_imp_max", "tol": 0.05, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance in the window", "expected": 10474.98046875}, {"key": "ubima_rc_peak_abs", "tol": 5e-05, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.021212393417954445}, {"key": "ubima_rc_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1318}, {"key": "ubima_syn_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (30 Hz)", "expected": 1360}]'::jsonb
     where app_slug = 'seismolord' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5a seismolord refused: seismolord/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '504c5962361e12aa8d3e607a99ecc5a2' and md5(coalesce(title, '')) = 'a3328273ed6e1f5e5cf888bd950b1ff7' and md5(coalesce(dataset, '')) = '46d7bac23cbee5cce31aab5e625bea31' and fields = '[{"key": "ubima_mean_velocity_ms", "tol": 0.05, "unit": "m/s", "label": "Mean sonic velocity in the window", "expected": 2991.2286066090837}, {"key": "ubima_twt_at_window_top_ms", "tol": 0.05, "unit": "ms", "label": "TWT at the top of the window", "expected": 1300}, {"key": "ubima_imp_max", "tol": 0.05, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance in the window", "expected": 10474.98046875}, {"key": "ubima_rc_peak_abs", "tol": 5e-05, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.021212393417954445}, {"key": "ubima_rc_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1318}, {"key": "ubima_syn_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (30 Hz)", "expected": 1360}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active) is not true then
    raise exception 'w5a seismolord refused: seismolord/beginner does not read back as its W5 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. The observed seismic trace is the 25 Hz synthetic arriving late by a lag this brief does not state. Run the bulk-shift scan on this trace (the shift explorer''s Observed trace setting "The brief''s trace"; the panel opens on a teaching trace) and read the panel: the suggested shift, and the correlation at zero lag, which is what the tie scores if you never shift it. Then flip the wavelet between 15 and 40 Hz and report the strongest synthetic amplitude and its time at each frequency. Tuning moves both.',
           title = 'Bulk shift and tuning on the basic_20 tie',
           dataset = 'wells/las/basic_20 + bulk shift',
           fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb
     where app_slug = 'seismolord' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5a seismolord refused: seismolord/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f00631b6f0fdf97f60cb989df036ee2d' and md5(coalesce(title, '')) = '48900a1c111c4c3e19996a98eda068ce' and md5(coalesce(dataset, '')) = '8006e0e511b8e482f3dcbc2ccf7900c8' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active) is not true then
    raise exception 'w5a seismolord refused: seismolord/intermediate does not read back as its W5 form';
  end if;

  raise notice 'w5a seismolord: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
